import static org.junit.Assert.*;

public class Partial_with_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullFieldTypeThrowsException() {
        Partial partial = new Partial(ISOChronology.getInstance());
        partial.with(null, 1);
    }

    @Test
    public void testWith_ExistingFieldUpdateValue() {
        DateTimeFieldType yearType = DateTimeFieldType.year();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, ISOChronology.getInstance());

        Partial updated = partial.with(yearType, 2021);

        assertEquals(1, updated.size());
        assertEquals(2021, updated.getValue(0));
        assertNotSame(partial, updated);
    }

    @Test
    public void testWith_ExistingFieldSameValueReturnsThis() {
        DateTimeFieldType yearType = DateTimeFieldType.year();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, ISOChronology.getInstance());

        Partial updated = partial.with(yearType, 2020);

        assertSame(partial, updated);
    }

    @Test
    public void testWith_AddNewField_SimpleInsertion() {
        DateTimeFieldType yearType = DateTimeFieldType.year();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();

        // Start with year
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, ISOChronology.getInstance());

        // Add month (month unit is smaller than year, so it should be inserted at index 0 or 1 depending on order logic)
        // The logic: compare unitField. If unitField (month) < loopUnitField (year), loopUnitField.compareTo(unitField) is > 0.
        // The loop breaks when unitField.compareTo(loopUnitField) > 0.
        Partial updated = partial.with(monthType, 12);

        assertEquals(2, updated.size());
        // Check if both exist
        boolean foundYear = false;
        boolean foundMonth = false;
        for (int i = 0; i < updated.size(); i++) {
            if (updated.getFieldType(i).equals(yearType)) {
                foundYear = true;
            }
            if (updated.getFieldType(i).equals(monthType)) {
                foundMonth = true;
            }
        }
        assertTrue(foundYear && foundMonth);
    }

    @Test
    public void testWith_AddNewField_WithRangeDurationType() {
        // This tests the branch: if (compare == 0) { if (fieldType.getRangeDurationType() == null) ... }
        // We need a field where unitField compareTo is 0, but rangeField is different.
        // In Joda, many fields have same unit duration but different range durations.

        DateTimeFieldType type1 = DateTimeFieldType.year();
        DateTimeFieldType type2 = DateTimeFieldType.century(); // Century is larger

        Partial partial = new Partial(new DateTimeFieldType[]{type1}, new int[]{2020}, ISOChronology.getInstance());
        Partial updated = partial.with(type2, 21);

        assertEquals(2, updated.size());
    }

    @Test
    public void testWith_AddNewField_UnitFieldNotSupported() {
        // If unitField.isSupported() is false, it skips the loop and inserts at index 0
        // This is hard to trigger with standard ISO fields, but we can attempt to mock or use a custom Chronology if needed.
        // However, for standard coverage, we ensure the loop logic is exercised.

        DateTimeFieldType yearType = DateTimeFieldType.year();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, ISOChronology.getInstance());

        // Using a field that is unlikely to have supported duration in standard chronology
        DateTimeFieldType customType = new DateTimeFieldType(DurationFieldType.day(), null, null) {
            @Override
            public DurationField getDurationType() {
                return DurationFieldTypes.day();
            }
        };

        Partial updated = partial.with(customType, 1);
        assertTrue(updated.size() >= 2);
    }

    @Test
    public void testWith_ComplexOrdering() {
        // Test the insertion point logic specifically
        // Sorting is largest-smallest. 
        // If unitField (new) > loopUnitField (existing), break and insert.

        DateTimeFieldType year = DateTimeFieldType.year();
        DateTimeFieldType month = DateTimeFieldType.monthOfYear();
        DateTimeFieldType day = DateTimeFieldType.dayOfMonth();

        Partial partial = new Partial(new DateTimeFieldType[]{month, day}, new int[]{1, 1}, ISOChronology.getInstance());

        // Adding year. Year unit > Month unit. 
        // loopUnitField (month) compareTo unitField (year) -> month is smaller, so compare < 0.
        // The loop continues.
        // loopUnitField (day) compareTo unitField (year) -> day is smaller, so compare < 0.
        // Then it inserts.

        Partial updated = partial.with(year, 2024);

        assertEquals(3, updated.size());
        // The logic finds position where unitField is "larger" than current.
        // If year is larger than month, it breaks at index 0.
    }
}
